//! The admin of [`Document`]: its list columns, search box and filters, generated by
//! `id-effect generate admin Document` from the entity's fields (edit them freely) and
//! registered in [`super::site`].
//!
//! Its pages are under `/admin/<tenant>/document`, and each one checks a permission
//! `admin.document.<action>` before any query. Nobody holds one until a role is granted it
//! ([`permissions`] lists them).
//!
//! Edits after generation (the README section "Back office" lists them all): documents are not
//! created here (they arrive through ingestion), the list leaves the body out, `status` filters
//! by the pipeline's statuses, the newest document comes first, the detail page's `labels`
//! relation is the label picker (add and remove a tenant's labels), and the bulk action
//! [`RERUN_EXTRACTION`] sends documents back through the AI stages.

use std::sync::Arc;
use std::time::Duration;

use id_effect::{Effect, succeed};
use id_effect_kit::admin::{
  AdminAction, AdminConfigError, AdminPermission, AdminSite, BulkAction, EntityAdmin, Filter,
};
use id_effect_kit::jobs::{JobOptions, JobQueueExt, RunAt};
use id_effect_kit::sql::SqlError;
use id_effect_kit::sql::repository::SortOrder;

use crate::App;
use crate::domain::{Document, DocumentStatus};
use crate::stages::ExtractJob;

/// The entity's name in its URLs and permissions.
pub const SLUG: &str = "document";

/// The actions this admin offers: list, view, update, delete and bulk, each its own permission.
/// Not create: documents arrive through ingestion (RPC or upload), never from the admin.
pub const ACTIONS: &[AdminAction] = &[
  AdminAction::List,
  AdminAction::View,
  AdminAction::Update,
  AdminAction::Delete,
  AdminAction::Bulk,
];

/// The bulk action sending the selected documents back through extraction, classification and
/// embedding (it needs `admin.document.bulk` and `admin.document.update`).
pub const RERUN_EXTRACTION: &str = "rerun_extraction";

/// The label key of [`RERUN_EXTRACTION`] (the attribute `rerun-extraction` of the message
/// `backoffice` in `locales/<locale>/backoffice.ftl`).
pub const RERUN_EXTRACTION_LABEL: &str = "backoffice.rerun-extraction";

/// How long after the bulk action's transaction starts the extraction jobs may run: the jobs
/// are queued on the main database, the status change in the tenant's, so the jobs wait for the
/// change to commit (the extraction stage acts only on a document that is `ingested`).
pub const RERUN_DELAY: Duration = Duration::from_secs(2);

/// How the admin shows [`Document`] records: every name is a field of the entity, checked
/// against its `Entity::FIELDS` when the site is built.
pub fn admin() -> EntityAdmin<Document> {
  EntityAdmin::default()
    .slug(SLUG)
    .list(["id", "title", "status", "source_id", "duplicate_of"])
    .search(["title", "body"])
    .filter(
      "status",
      Filter::choices(DocumentStatus::ALL.map(DocumentStatus::as_str)),
    )
    .sortable(["id", "title", "status"])
    .default_sort("id", SortOrder::Desc)
}

/// The bulk action [`RERUN_EXTRACTION`] of `tenant` over `app`: each selected document is set
/// back to `ingested` (through the admin's writer, in the action's transaction with its audit
/// record) and its [`ExtractJob`] is queued to run after [`RERUN_DELAY`].
pub fn rerun_extraction(app: &Arc<App>, tenant: &str) -> BulkAction<Document> {
  let (app, tenant) = (Arc::clone(app), tenant.to_owned());
  BulkAction::new(
    RERUN_EXTRACTION,
    RERUN_EXTRACTION_LABEL,
    move |ctx, documents: Vec<Document>| {
      documents
        .into_iter()
        .fold(succeed(()), |done: Effect<(), SqlError>, mut document| {
          DocumentStatus::Ingested
            .as_str()
            .clone_into(&mut document.status);
          let update = ctx.update(document);
          let (app, tenant) = (Arc::clone(&app), tenant.clone());
          done.flat_map(move |()| {
            update.flat_map(move |document| {
              let job = ExtractJob {
                tenant: tenant.clone(),
                document_id: document.id,
              };
              let options = JobOptions::new().run_at(RunAt::After(RERUN_DELAY));
              app
                .jobs
                .enqueue(job, options)
                .map_err(|e| SqlError::TransactionFailed(format!("job queue: {e}")))
                .map(move |_| {
                  app
                    .status
                    .announce(&tenant, document.id, DocumentStatus::Ingested);
                })
            })
          })
        })
    },
  )
}

/// Adds the [`Document`] admin of `tenant` over `app` to `site`, with [`rerun_extraction`].
pub fn register(
  site: AdminSite,
  app: &Arc<App>,
  tenant: &str,
) -> Result<AdminSite, AdminConfigError> {
  site.try_register(admin().action(rerun_extraction(app, tenant)))
}

/// The permissions of [`ACTIONS`], `admin.document.<action>`: the ones a role can be granted.
pub fn permissions() -> Result<Vec<AdminPermission>, AdminConfigError> {
  let info = admin().info()?;
  let offered = |permission: &AdminPermission| ACTIONS.contains(&permission.action());
  Ok(info.permissions.into_iter().filter(offered).collect())
}

#[cfg(test)]
mod tests {
  use std::sync::Arc;

  use id_effect_kit::admin::AdminDatabase;
  use id_effect_kit::authz::{
    BasicPrincipal, CurrentPrincipal, Decision, Guard, Policy, Rbac, require_role,
  };
  use id_effect_kit::sql::{Dialect, TestSqlClient};

  use super::*;
  use crate::admin::tests::test_app;
  use crate::admin::{PREFIX, policy, router};

  #[test]
  fn the_configuration_matches_the_entity() {
    let info = admin().info().expect("every name is a field of Document");
    assert_eq!(info.slug, SLUG);
    assert_eq!(
      info.list,
      ["id", "title", "status", "source_id", "duplicate_of"]
    );
    let with_action = admin().action(rerun_extraction(&test_app(), "acme"));
    assert_eq!(with_action.info().unwrap().actions, [RERUN_EXTRACTION]);
  }

  #[test]
  fn nothing_is_allowed_until_granted() {
    let policy = policy(Rbac::default()).expect("the admin builds");
    let nobody = CurrentPrincipal::new(BasicPrincipal::new("nobody"));
    for permission in admin().info().unwrap().permissions {
      let decision = policy.decide_now(&nobody, &permission);
      assert!(matches!(decision, Some(Decision::Deny(_))), "{permission}");
    }
  }

  #[test]
  fn only_the_offered_actions_can_be_granted() {
    let rbac = Rbac::builder().grant("root", ["*"]).build();
    let policy = policy(rbac).expect("the admin builds");
    let root = CurrentPrincipal::new(BasicPrincipal::new("root").with_role("root"));
    for permission in admin().info().unwrap().permissions {
      let allowed = policy.decide_now(&root, &permission) == Some(Decision::Allow);
      assert_eq!(
        allowed,
        ACTIONS.contains(&permission.action()),
        "{permission}"
      );
    }
    assert_eq!(permissions().unwrap().len(), ACTIONS.len());
  }

  #[test]
  fn every_page_is_behind_the_guard() {
    let db = AdminDatabase::new(Arc::new(TestSqlClient::new()), Dialect::Postgres);
    let guard = Guard::new("staff", require_role("staff"));
    let routes =
      router::<()>(&test_app(), "acme", guard, Rbac::default(), db).expect("the admin builds");
    let report = routes.access_report();
    assert!(report.public.is_empty(), "{:?}", report.public);
    let list = format!("GET {PREFIX}/{SLUG}");
    assert!(
      report
        .guarded
        .iter()
        .any(|(route, _)| route.as_str() == list)
    );
  }
}
